```
FinalHeader memory last = h;
bytes[] calldata desc = steps[i].descendants;
for (uint256 k = 0; k < desc.length; ++k) {
    (FinalHeader memory d,) = _parse(desc[k]);
    if (d.number != last.number + 1 || RlpReader.toItem(desc[k]).at(0).toBytes32() != last.hash) revert NotLinked(k);
